162	    }
163	
164	    public void setNamesakeCount(Integer namesakeCount) {
165	        this.namesakeCount = namesakeCount;
166	    }
167	
168	    public Integer getHouseholdSize() {
169	        return this.householdSize;
170	    }
171	
172	    public void setHouseholdSize(Integer householdSize) {
173	        this.householdSize = householdSize;
174	    }
175	
176	    public Boolean getBulkSignupWarning() {
177	        return this.bulkSignupWarning;
178	    }
