182	    }
183	
184	    public Boolean getPossibleDuplicate() {
185	        return this.possibleDuplicate;
186	    }
187	
188	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
189	        this.possibleDuplicate = possibleDuplicate;
190	    }
191	
192	    public Integer getPossibleDuplicateOf() {
193	        return this.possibleDuplicateOf;
194	    }
195	
196	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
197	        this.possibleDuplicateOf = possibleDuplicateOf;
198	    }
199	
200	    protected Set<Pet> getPetsInternal() {
201	        if (this.pets == null) {
202	            this.pets = new HashSet<>();
203	        }
204	        return this.pets;
205	    }
206	
207	    protected void setPetsInternal(Set<Pet> pets) {
208	        this.pets = pets;
209	    }
210	
211	    public List<Pet> getPets() {
212	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
213	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
214	        return Collections.unmodifiableList(sortedPets);
215	    }
216	
217	    public void setPets(List<Pet> pets) {
218	        this.pets = new HashSet<>(pets);
219	    }
220	
221	    public void addPet(Pet pet) {
222	        getPetsInternal().add(pet);
223	        pet.setOwner(this);
224	    }
225	
226	    /**
227	     * Return the Pet with the given name, or null if none found for this Owner.
228	     *
229	     * @param name to test
230	     * @return true if pet name is already in use
231	     */
232	    public Pet getPet(String name) {
233	        return getPet(name, false);
234	    }
235	
236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name, boolean ignoreNew) {
243	        name = name.toLowerCase();
244	        for (Pet pet : getPetsInternal()) {
245	            if (!ignoreNew || !pet.isNew()) {
246	                String compName = pet.getName();
247	                compName = compName.toLowerCase();
248	                if (compName.equals(name)) {
249	                    return pet;
250	                }
251	            }
252	        }
253	        return null;
254	    }
255	
256	    public Pet getPet(Integer petId) {
257	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
258	    }
259	
260	    @Override
261	    public String toString() {
262	        return new ToStringCreator(this)
263	
264	            .append("id", this.getId())
265	            .append("new", this.isNew())
266	            .append("lastName", this.getLastName())
267	            .append("firstName", this.getFirstName())
268	            .append("address", this.address)
269	            .append("city", this.city)
270	            .append("telephone", this.telephone)
271	            .toString();
272	    }
273	}
