26	/**
27	 * Maps Owner & OwnerDto using Mapstruct
28	 */
29	@Mapper(uses = PetMapper.class)
30	public interface OwnerMapper {
31	
32	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
33	    @Mapping(target = "initials", expression = "java(initials(owner))")
34	    @Mapping(target = "locality", expression = "java(locality(owner))")
35	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
36	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
37	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
38	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
40	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
41	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /** The owner's name formatted as 'LastName, FirstName'. */
47	    default String displayName(Owner owner) {
48	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
49	    }
50	
51	    /**
52	     * The canonical region taken from the owner's region-and-hash identity: the REGION portion of the
53	     * customerCode (see {@link CustomerCode}). Falls back to deriving the region directly from the
54	     * city and postcode (see {@link Locality}) for an owner that has no customerCode yet.
55	     */
56	    default String locality(Owner owner) {
57	        if (owner == null) {
58	            return null;
59	        }
60	        String region = CustomerCode.regionOf(owner.getCustomerCode());
61	        return region != null ? region : Locality.of(owner.getCity(), owner.getPostcode());
62	    }
63	
64	    /**
65	     * The owner's IANA timezone (see {@link RegionTimezone}), derived from the owner's
66	     * {@link #locality(Owner) locality} (region): NSW->Australia/Sydney, VIC->Australia/Melbourne,
67	     * QLD->Australia/Brisbane. {@code null} when the region has no timezone.
68	     */
69	    default String timezone(Owner owner) {
70	        return owner == null ? null : RegionTimezone.of(locality(owner));
71	    }
72	
73	    /** The upper-cased first letters of the first and last name, e.g. 'J.S.'. */
74	    default String initials(Owner owner) {
75	        return owner == null ? null
76	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
77	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
78	    }
79	
80	    /**
81	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
82	     * last two digits of the registration date's year, e.g. 'NSW-1A2B3C4D-M26'.
83	     */
84	    default String membershipNumber(Owner owner) {
85	        return MembershipNumber.of(owner);
86	    }
87	
88	    /**
89	     * The owner's check digit (see {@link CheckDigit}): the Luhn check digit over the digits of the
90	     * customer code.
91	     */
92	    default Integer checkDigit(Owner owner) {
93	        return owner == null ? null : CheckDigit.of(owner.getCustomerCode());
94	    }
95	
96	    /**
97	     * The owner's membership points (see {@link MembershipPoints}): a score that starts at 0 and
98	     * gains 2 for a present email address, 1 for a unique name (namesakeCount is zero), 2 for a
99	     * household of 3 or more and 3 for tenure over a year.
100	     */
101	    default Integer membershipPoints(Owner owner) {
102	        return MembershipPoints.of(owner);
103	    }
104	
105	    /**
106	     * The owner's membership level (see {@link MembershipLevel}): the {@link #membershipPoints(Owner)
107	     * membership points} banded into a number from 1 to 4 (1 for 0-1 points, 2 for 2-3, 3 for 4-5,
108	     * 4 for 6 or more).
109	     */
110	    default Integer membershipLevel(Owner owner) {
111	        return MembershipLevel.forPoints(MembershipPoints.of(owner));
112	    }
113	
114	    /**
115	     * The owner's preferred contact channel (see {@link ContactPreference}): 'EMAIL' when an email
116	     * address is present, otherwise 'PHONE'.
117	     */
118	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
119	        ContactPreference preference = ContactPreference.of(owner);
120	        return preference == null ? null : OwnerDto.ContactPreferenceEnum.valueOf(preference.name());
121	    }
122	
123	    /**
124	     * The owner's derived identity key (see {@link IdentityKey}): the canonical telephone, email and
125	     * household id joined by '|'. A read-only summary of the owner's contact identity; duplicate
126	     * detection itself keys off the household id.
127	     */
128	    default String identityKey(Owner owner) {
129	        return owner == null ? null : IdentityKey.forOwner(owner);
130	    }
131	
132	    /**
133	     * The owner's age band (see {@link AgeBand}): 'MINOR' under 18, 'ADULT' from 18 to 64 and
134	     * 'SENIOR' at 65 or older, measured from the birth date against the registration date, or
135	     * {@code null} when no birth date was given.
136	     */
137	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
138	        AgeBand band = AgeBand.of(owner);
139	        return band == null ? null : OwnerDto.AgeBandEnum.valueOf(band.name());
140	    }
141	
142	    /**
143	     * The stored E.164 telephone formatted for humans (see
144	     * {@link TelephoneNormalizer#toDisplay(String)}): the country code, a space, then the national
145	     * digits grouped in threes, e.g. '+61 412 345 678'. The raw telephone stays in E.164 form.
146	     */
147	    default String telephoneDisplay(Owner owner) {
148	        return owner == null ? null : TelephoneNormalizer.toDisplay(owner.getTelephone());
149	    }
150	
151	    Owner toOwner(OwnerDto ownerDto);
152	
153	    @Mapping(target = "id", ignore = true)
154	    @Mapping(target = "pets", ignore = true)
155	    Owner toOwner(OwnerFieldsDto ownerDto);
156	
157	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
158	
159	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
160	
161	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
162	        OwnerPageDto ownerPageDto = new OwnerPageDto();
163	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
164	        ownerPageDto.setPage(ownerPage.getNumber());
165	        ownerPageDto.setSize(ownerPage.getSize());
166	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
167	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
168	        return ownerPageDto;
169	    }
170	}
