1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Pinned city-to-region reference table. An owner's locality is the canonical region of its city;
7	 * a city that is not in the table has region {@link #UNKNOWN}. Pure lookup with no dependency on
8	 * other owners, so it is derived at response time rather than stored on the entity.
9	 */
10	public final class CityRegion {
11	
12	    /** The region reported for any city not in {@link #CITY_REGIONS}. */
13	    public static final String UNKNOWN = "UNKNOWN";
14	
15	    /** City -> canonical region. */
16	    private static final Map<String, String> CITY_REGIONS = Map.of(
17	            "Sydney", "NSW",
18	            "Melbourne", "VIC",
19	            "Brisbane", "QLD");
20	
21	    private CityRegion() {
22	    }
23	
24	    /**
25	     * The canonical region for {@code city}, or {@link #UNKNOWN} when the city is {@code null} or not
26	     * in the table.
27	     */
28	    public static String of(String city) {
29	        return city == null ? UNKNOWN : CITY_REGIONS.getOrDefault(city, UNKNOWN);
30	    }
31	}
